{
  "totalAmount": {{checkout_amount}}, // enter the total order amount here in paisa (10000 = Rs.100)
  "type": "{{split_type}}", // ABSOLUTE (values in paisa) or PERCENT (values are percentages)
  "accountsSplit": [
    {
      "accountId": "{{split_account_id_1}}", // enter linked account 1 id here (from Get Split Account Info)
      "value": {{split_value_1}} // enter the amount/percentage for account 1 here
    },
    {
      "accountId": "{{split_account_id_2}}", // enter linked account 2 id here
      "value": {{split_value_2}} // enter the amount/percentage for account 2 here
    }
  ]
}

{
  "merchantOrderId": "{{merchant_order_id}}", // auto-generated each run (ORDER_<timestamp>)
  "amount": {{checkout_amount}}, // enter your amount here in paisa (min 100; 10000 = Rs.100)
  "expireAfter": {{expire_after}}, // enter payment link validity here in seconds (300-3600)
  "paymentFlow": {
    "type": "PG_CHECKOUT",
    "merchantUrls": {
      "redirectUrl": "{{redirect_url}}" // enter the URL to redirect the customer to after payment
    }
  },
  "splitSettlementInfo": {
    "type": "{{split_type}}", // ABSOLUTE (values in paisa) or PERCENT (values are percentages)
    "accountsSplit": [
      {
        "accountId": "{{split_account_id_1}}", // enter linked account 1 id here
        "value": {{split_value_1}} // enter the amount/percentage for account 1 here
      },
      {
        "accountId": "{{split_account_id_2}}", // enter linked account 2 id here
        "value": {{split_value_2}} // enter the amount/percentage for account 2 here
      }
    ]
  }
}
